import json
for step in [1,40,80,120,160,200]:
    print("="*30,"STEP",step,"="*30)
    with open(f'results/recorded_run/rollouts/{step}.jsonl') as f:
        for ln,line in enumerate(f):
            d=json.loads(line)
            print(f"--- row{ln} keys={sorted(d.keys())} ---")
            for k,v in d.items():
                if k in ('prompt','responses','response','trajectory','steps','messages','obs','actions','turns'):
                    sv=str(v)
                    print(f"  [{k}] len={len(sv)} :: {sv[:1500]}")
                else:
                    print(f"  [{k}] = {str(v)[:300]}")
            if ln>=1: break
EOF

