python3 -I - <<'EOF'
import json,glob,os
rows={}
for p in sorted(glob.glob('results/recorded_run/metrics/*.json'), key=lambda x:int(os.path.basename(x)[:-5])):
    d=json.load(open(p)); rows[int(d['step'])]=d['metrics']
def f(v):
    try: return float(v)
    except: return None
vk=[k for k in rows[1] if k.startswith('val-')]
print("VAL KEYS:",vk)
for s in sorted(rows):
    if s%20==0 or s in (1,40,80,120,160,200):
        print(s, {k.split('/')[-1]: f(rows[s].get(k)) for k in vk})
EOF

