import json,glob,os
rows={}
for p in sorted(glob.glob('results/recorded_run/metrics/*.json'), key=lambda x:int(os.path.basename(x)[:-5])):
    d=json.load(open(p)); rows[int(d['step'])]=d['metrics']
def f(v):
    try: return float(v)
    except: return None
allneg=[]; zeroadv=[]; highclip=[]
for s in sorted(rows):
    r=rows[s]
    if f(r.get('critic/rewards/max')) is not None and f(r.get('critic/rewards/max'))<=0 and f(r.get('critic/rewards/mean'))<=-0.95:
        allneg.append(s)
    if f(r.get('critic/advantages/max'))==0.0 and f(r.get('critic/advantages/min'))==0.0:
        zeroadv.append(s)
    if (f(r.get('response_length/clip_ratio')) or 0)>0.2:
        highclip.append(s)
print("steps with mean reward <= -0.95 and max<=0:", len(allneg), allneg)
print("steps with identically zero advantage:", len(zeroadv), zeroadv)
print("steps with response clip ratio > 0.2:", len(highclip), highclip[:40])
print()
print("=== regularization config ===")
for k in ['actor/kl_loss','actor/kl_coef','actor/entropy','actor/pg_clipfrac']:
    print(k, rows[120].get(k))
EOF

