rows={}
for p in sorted(glob.glob('results/recorded_run/metrics/*.json'), key=lambda x:int(os.path.basename(x)[:-5])):
    d=json.load(open(p)); rows[int(d['step'])]=d['metrics']
def f(v):
    try:return float(v)
    except:return None
print("retok vs length ordering (is retok downstream of length?):")
for s in range(160,190,2):
    r=rows[s]
    print(f"  {s}: retok={f(r.get('verl_tool/retokenization_diff/mean')):.3f} len={f(r.get('response_length/mean')):6.0f} turns={f(r.get('num_turns/mean')):.2f}")
print()
print("first step retok > 0:", next((s for s in sorted(rows) if (f(rows[s].get('verl_tool/retokenization_diff/mean')) or 0)>0), None))
print("first step clip > 0.02:", next((s for s in sorted(rows) if (f(rows[s].get('response_length/clip_ratio')) or 0)>0.02), None))
EOF

